using System.Net;
using System.Net.Http.Json;
using JaxPower.Ipqc.Api.Services;
using Microsoft.Extensions.DependencyInjection;
using Xunit;
using static JaxPower.Ipqc.Api.Tests.NgPicSelectionFixture;

namespace JaxPower.Ipqc.Api.Tests;

public sealed class NgPicSelectionIdentityTests
{
    [Fact] public void Fixed_wire_vector_has_independent_SHA256_and_set_semantics() {
        Guid Id(int n) => Guid.Parse("00000000-0000-0000-0000-" + n.ToString("D12"));
        var b = new JaxPower.Ipqc.Api.Contracts.NgPicBatchInput(Id(10), 1, Id(2), 2, "synthetic-vector", 7,
            new(Id(3), 1, "SelectNgPics", Id(4), Id(5), Id(6), Id(7), 7, 9, [Id(9), Id(8)], null), new(Id(6), "Synthetic transport proof"));
        const string expected = """{"domain":"ng-pic-selection","v":1,"environment":"synthetic-vector","task":"00000000-0000-0000-0000-000000000001","line":"00000000-0000-0000-0000-000000000002","workflow":2,"operation":"00000000-0000-0000-0000-000000000003","kind":"SelectNgPics","item":"00000000-0000-0000-0000-000000000004","attempt":"00000000-0000-0000-0000-000000000005","source":"00000000-0000-0000-0000-000000000006","contributorAssertion":"00000000-0000-0000-0000-000000000007","base":7,"local":9,"picIds":["00000000-0000-0000-0000-000000000008","00000000-0000-0000-0000-000000000009"],"predecessor":null}""";
        var payload = NgPicSelectionCanonical.Operation(Id(1), b); Assert.Equal(expected, payload);
        // Independent PowerShell SHA256 over the literal UTF8 vector, not generated by the canonicalizer.
        Assert.Equal("E977394C78AD491C4F1E939611DFB92C29BF77F8C4CB7E28746637E1FE141145", DraftCanonical.Hash(payload));
        Assert.Equal(payload, NgPicSelectionCanonical.Operation(Id(1), b with { SourceProof = null, Operation = b.Operation with { PicIds = [Id(8), Id(9)] } }));
        foreach (var changed in new[] { b with { Operation = b.Operation with { PicIds = [] } }, b with { ExpectedEnvironmentId = "other" }, b with { ExpectedTaskLineId = Id(11) },
            b with { Operation = b.Operation with { TaskItemId = Id(11) } }, b with { Operation = b.Operation with { InspectionAttemptId = Id(11) } },
            b with { Operation = b.Operation with { SourceWorkContextId = Id(11) } }, b with { Operation = b.Operation with { ContributorUserIdAssertion = Id(11) } },
            b with { Operation = b.Operation with { OriginLocalEditVersion = 10 } }, b with { Operation = b.Operation with { BaseDraftVersion = 8 } } })
            Assert.NotEqual(payload, NgPicSelectionCanonical.Operation(Id(1), changed));
        Assert.NotEqual(payload, NgPicSelectionCanonical.Operation(Id(11), b));
    }
    [Fact] public async Task Direct_caller_cannot_mutate_selected_set_during_authority_wait() { await using var f = await PersonalSessionFixture.CreateAsync(); await Mutable(f); }
    internal static async Task Mutable(PersonalSessionFixture f) {
        var u = await Setup(f); var b = Input(u); f.Fault.Arm("ApplicationUsers");
        await using var scope = f.Factory.Services.CreateAsyncScope(); var service = scope.ServiceProvider.GetRequiredService<SharedDraftService>();
        var pending = service.AcceptNgPicsAsync(u.S.TaskId, b, WorkContextFixture.Principal(u.S.B), default);
        try { await f.Fault.Entered.Task.WaitAsync(TimeSpan.FromSeconds(15)); b.Operation.PicIds.Clear(); b.Operation.PicIds.Add(u.Pics[1].PicId); }
        finally { f.Fault.Release.TrySetResult(); }
        var result = await pending; Assert.Equal(u.Pics[0].PicId, Assert.Single(result.Operation.SelectedPics).PicId);
    }
    [Fact] public async Task Every_existing_domain_and_PIC_share_one_native_operation_namespace() { await using var p = await PhotoFixture.Create(); await Namespace(p); }
    internal static async Task Namespace(PhotoFixture p) {
        var f = p.F; var u = await Setup(f); var s = u.S; var pic = (await Accept(u, Input(u))).Operation;
        var (photo, reference) = await DraftEvidenceAssessmentTests.Photo(s); var binding = new BindingSetup(s, u.Sample!, photo, reference!);
        var sample = s.Batch(s.Capture(version: 3), 3); var removed = ItemRemovalTests.Input(s, 3);
        var attachment = DraftAttachmentTests.Input(s, photo, 3, previous: reference, kind: "DetachAttachment");
        var unable = UnableToMeasureTests.Input(new(s, photo, reference!), 3); var bind = SampleEvidenceTests.Input(binding, 3); var header = BasicInformationFixture.Input(s, 3);
        var before = await Facts(f);
        var attempts = new[] {
            s.Client().PostAsJsonAsync(s.Root + "/operation-batches", sample with { Operations = [sample.Operations[0] with { OperationId = pic.OperationId }] }),
            s.Client().PostAsJsonAsync(ItemRemovalTests.Url(s), removed with { Operation = removed.Operation with { OperationId = pic.OperationId } }),
            s.Client().PostAsJsonAsync(DraftAttachmentTests.Url(s), attachment with { Operations = [attachment.Operations[0] with { OperationId = pic.OperationId }] }),
            s.Client().PostAsJsonAsync(UnableToMeasureTests.Url(s), unable with { Operation = unable.Operation with { OperationId = pic.OperationId } }),
            s.Client().PostAsJsonAsync(SampleEvidenceTests.Url(s), bind with { Operation = bind.Operation with { OperationId = pic.OperationId, BindingId = pic.OperationId } }),
            s.Client().PostAsJsonAsync(BasicInformationFixture.WriteUrl(s), header with { Operation = header.Operation with { OperationId = pic.OperationId } }) };
        foreach (var r in await Task.WhenAll(attempts)) { Assert.Equal(HttpStatusCode.Conflict, r.StatusCode); Assert.Contains("OperationIdentityConflict", await r.Content.ReadAsStringAsync()); }
        Assert.Equal(before, await Facts(f));
        var h = (await BasicInformationFixture.Accept(s, header)).Operation;
        var bound = (await SampleEvidenceTests.Accept(binding, SampleEvidenceTests.Input(binding, 4))).Operation;
        var other = (await s.Read())!.CurrentAttempts.Single(x => x.TaskItemId != s.ItemId);
        var rm = (await ItemRemovalTests.Accept(s, ItemRemovalTests.Input(s, 5, other))).Operation;
        var un = (await UnableToMeasureTests.Accept(new(s, photo, reference!), UnableToMeasureTests.Input(new(s, photo, reference!), 6))).Operation;
        before = await Facts(f);
        foreach (var id in new[] { u.Sample!.OperationId, reference!.OperationId, h.OperationId, bound.OperationId, rm.OperationId, un.OperationId }) {
            var b = Input(u, 7, [], pic); var r = await s.Client().PostAsJsonAsync(Url(s), b with { Operation = b.Operation with { OperationId = id } });
            Assert.Equal(HttpStatusCode.Conflict, r.StatusCode); Assert.Contains("OperationIdentityConflict", await r.Content.ReadAsStringAsync());
        }
        Assert.Equal(before, await Facts(f));
    }
}
